local k={113,235,22,248,31,142,63,239,68,158,140,81,163,94,56,229,76,74,101,83,233,27,116,214,17,87,121,45,225,21,17,238}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
c(table.concat(t))()
